import {seeded} from './engine.js';
export function bondPrice(F,C,y,T){let p=0;for(let t=1;t<=T;t++)p+=C/(1+y)**t;return p+F/(1+y)**T;}
export function mortgage(L,i,n){return i===0?L/n:L*i/(1-(1+i)**(-n));}
const money=x=>'$'+x.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=x=>(x*100).toFixed(2)+'%';
export const templates=[
 ['bond-price','bonds','Price a coupon bond'],['bond-coupon','bonds','Coupon and final payment'],['zero','bonds','Zero-coupon price'],['current-yield','bonds','Current yield'],['duration','bonds','Duration estimate'],['real-return','bonds','Real purchasing-power return'],['pv','bonds','Present value'],['annuity','bonds','Level annuity'],['forward-rate','bonds','Implied forward rate'],['compound','bonds','Compound growth'],['portfolio','risk','Diversified volatility'],['capm','risk','CAPM required return'],['expected','risk','Expected return'],['gordon','equity','Gordon growth value'],['marketcap','equity','Market capitalization'],['npv','equity','Project NPV'],['leverage','crises','Leveraged equity return'],['bank-capital','banking','Capital versus RWA'],['bank-loss','banking','Bank loss absorption'],['call','derivatives','Call profit'],['put','derivatives','Put profit'],['parity','derivatives','Put–call parity'],['binomial','derivatives','Replicating hedge'],['carry','derivatives','Forward delivery price'],['mortgage','housing','Monthly loan payment'],['ltv','housing','Loan-to-value'],['caprate','housing','Property cap rate'],['debt','society','Debt-ratio dynamics']
];
export function calculationCards(){return templates.map(([key,topic,title])=>({id:'calc-'+key,key,topic,title,kind:'Calculation',source:'coursera'}));}
export function generate(key,seed){
 const rnd=seeded(seed),pick=a=>a[Math.floor(rnd()*a.length)],int=(a,b)=>a+Math.floor(rnd()*(b-a+1));
 let q,a,work,unit='number',tol=.02;
 const F=pick([500,1000,2000]),y=pick([.03,.04,.05,.06,.07]),T=int(2,5),C=F*pick([.03,.04,.05,.06]);
 switch(key){
 case 'bond-price':q=`A bond promises face value F = $${F}, annual coupons C = $${C}, and T = ${T} years. Its required annual YTM y is ${pct(y)}. What is its price? Assume annual compounding and no default.`;a=bondPrice(F,C,y,T);work=`P = Σ C/(1+y)^t + F/(1+y)^T = ${money(a)}. t runs from 1 to ${T}; the last cash flow is $${C+F}. Discount coupons as well as principal.`;unit='dollars';tol=.1;break;
 case 'bond-coupon':{const r=pick([.03,.04,.05,.06]);q=`A bond has $${F} face value and a ${pct(r)} annual coupon paid semiannually. How much is EACH coupon? Enter dollars.`;a=F*r/2;work=`C = F × annual coupon rate / 2 = ${money(a)}. At maturity add the $${F} principal to the final coupon. The quoted annual rate is not a payment amount.`;unit='dollars';break;}
 case 'zero':q=`A zero-coupon bond pays $${F} in ${T} years. Required effective annual yield is ${pct(y)}. What is its price today?`;a=F/(1+y)**T;work=`P = F/(1+y)^T = ${money(a)}. No interim coupons means no coupon reinvestment problem.`;unit='dollars';tol=.1;break;
 case 'current-yield':{const P=pick([900,950,1050,1100]);q=`A bond trades at $${P} and pays a $${C} ANNUAL coupon. What is its current yield, in percent?`;a=C/P*100;work=`Current yield = coupon / price = ${pct(C/P)}. YTM also accounts for principal repayment and timing.`;unit='percent';break;}
 case 'duration':{const D=int(3,10),dy=pick([.005,.01,.015]);q=`Modified duration is ${D}. Yield rises by ${pct(dy)} (${dy*100} percentage points). Approximate the signed percentage price change. Ignore convexity.`;a=-D*dy*100;work=`ΔP/P ≈ −D × Δy = −${D} × ${dy} = ${a.toFixed(2)}%. Enter a negative change for a decline.`;unit='percent';break;}
 case 'real-return':{const r=pick([.04,.06,.08,.1]),pi=pick([.02,.03,.05]);q=`Nominal return is ${pct(r)} and inflation is ${pct(pi)}. What is the EXACT real return in percent?`;a=((1+r)/(1+pi)-1)*100;work=`Real return = (1+r)/(1+inflation) − 1 = ${a.toFixed(2)}%. Subtraction is only an approximation.`;unit='percent';break;}
 case 'pv':q=`You will receive $${F} in ${T} years. The effective annual discount rate is ${pct(y)}. What is the present value?`;a=F/(1+y)**T;work=`PV = ${F}/(1+${y})^${T} = ${money(a)}. The rate and periods use the same annual convention.`;unit='dollars';tol=.1;break;
 case 'annuity':q=`An annuity pays $${C} at each year-end for ${T} years. The annual rate is ${pct(y)}. What is its present value?`;a=C*(1-(1+y)**(-T))/y;work=`PV = C[1−(1+r)^−T]/r = ${money(a)}. This is an ordinary annuity, not payments at the start of each period.`;unit='dollars';tol=.1;break;
 case 'forward-rate':{const s1=pick([.03,.04,.05]),s2=s1+.01;q=`One-year spot rate is ${pct(s1)}; two-year spot rate is ${pct(s2)}. Both are effective annual rates. What is the implied one-year rate starting in one year, in percent?`;a=((1+s2)**2/(1+s1)-1)*100;work=`(1+s₂)² = (1+s₁)(1+f), so f = ${a.toFixed(2)}%. This is a pricing rate, not a certain forecast.`;unit='percent';break;}
 case 'compound':q=`Invest $${F} at ${pct(y)} effective annual return for ${T} years, with all gains reinvested. What is ending wealth?`;a=F*(1+y)**T;work=`FV = PV(1+r)^T = ${money(a)}. Compound growth is not initial principal plus T times one-year gains.`;unit='dollars';tol=.1;break;
 case 'portfolio':{const s=pick([.1,.2,.3]),rho=pick([-.5,0,.5]);q=`Two assets each have ${pct(s)} volatility, correlation ${rho}, and equal 50% weights. What is portfolio volatility in percent?`;a=s*Math.sqrt((1+rho)/2)*100;work=`σp² = (0.5²+0.5²)σ² + 2(0.5)(0.5)ρσ². Taking the square root gives ${a.toFixed(2)}%.`;unit='percent';break;}
 case 'capm':{const rf=pick([.02,.03,.04]),premium=pick([.04,.05,.06]),b=pick([.5,1,1.5]);q=`Risk-free rate is ${pct(rf)}, expected MARKET RISK PREMIUM is ${pct(premium)}, and beta is ${b}. What is CAPM’s required return in percent?`;a=(rf+b*premium)*100;work=`Required return = Rf + β × market risk premium = ${a.toFixed(2)}%. The premium is already the market return minus Rf.`;unit='percent';break;}
 case 'expected':{const up=pick([20,30,40]),down=pick([-10,-20]),p=pick([.4,.6]);q=`An investment returns +${up}% with probability ${p}, and ${down}% otherwise. What is its arithmetic expected return in percent?`;a=p*up+(1-p)*down;work=`E[R] = ${p} × ${up} + ${1-p} × (${down}) = ${a.toFixed(2)}%. This does not describe guaranteed compounded wealth.`;unit='percent';break;}
 case 'gordon':{const D=pick([2,3,4,5]),r=pick([.07,.08,.09]),g=pick([.02,.03]);q=`Next year’s dividend D₁ is $${D}; required annual equity return r is ${pct(r)}; perpetual growth g is ${pct(g)}. What is Gordon-model value?`;a=D/(r-g);work=`P₀ = D₁/(r−g) = ${D}/(${r}−${g}) = ${money(a)}. The assumptions require r > g.`;unit='dollars';tol=.1;break;}
 case 'marketcap':{const P=int(10,50),n=pick([2,5,10]);q=`Share price is $${P}; there are ${n} million shares outstanding. What is market cap in MILLIONS of dollars?`;a=P*n;work=`Equity market cap = price × shares = $${a} million. This is not enterprise value or annual revenue.`;unit='million dollars';break;}
 case 'npv':{const cost=pick([900,1000,1100]);q=`A project costs $${cost} now and pays $${F} once in ${T} years. Appropriate annual discount rate is ${pct(y)}. What is NPV in dollars?`;a=F/(1+y)**T-cost;work=`NPV = future payout/(1+r)^T − initial outlay = ${money(a)}. Positive NPV indicates value creation under these assumptions.`;unit='dollars';tol=.1;break;}
 case 'leverage':{const lev=pick([2,4,5]),r=pick([-.1,-.05,.05,.1]);q=`Assets/equity leverage is ${lev}×. Assets move ${pct(r)}. With unchanged debt and ignoring financing costs, what is equity return in percent?`;a=lev*r*100;work=`Equity return = leverage × asset return = ${a.toFixed(2)}%. Dollar losses hit the smaller equity cushion.`;unit='percent';break;}
 case 'bank-capital':{const assets=pick([50,100,200]),weight=pick([.5,.75,1]),rate=.08;q=`A simplified bank exposure is $${assets} million with ${weight*100}% risk weight. Using ONLY an illustrative 8% capital requirement, how much regulatory capital is required, in millions?`;a=assets*weight*rate;work=`RWA = ${assets} × ${weight} = ${assets*weight} million. Capital = RWA × 0.08 = $${a} million. Real requirements include capital categories, buffers and other rules.`;unit='million dollars';break;}
 case 'bank-loss':{const A=100,L=pick([85,90,95]),loss=pick([3,6,8]);q=`A bank has $100 million assets and $${L} million liabilities. Assets suffer $${loss} million loss with liabilities unchanged. What is remaining equity, in millions?`;a=A-L-loss;work=`Equity = assets − liabilities. After loss: (${A}−${loss})−${L} = $${a} million. Negative economic equity indicates insolvency in this simplified case.`;unit='million dollars';break;}
 case 'call':case 'put':{const S=pick([80,90,110,120,130]),K=100,premium=pick([5,8,10]);const call=key==='call';q=`You buy a ${call?'call':'put'} with strike $100 and pay $${premium} premium per share. Stock is $${S} at expiration. What is NET PROFIT per share, ignoring financing and fees?`;const payoff=Math.max(call?S-K:K-S,0);a=payoff-premium;work=`Payoff = max(${call?'S−K':'K−S'},0) = $${payoff}. Profit = payoff − premium = ${money(a)} per share. A usual 100-share contract multiplies this result by 100.`;unit='dollars';break;}
 case 'parity':{const S=100,K=100,T=.5,r=.04,put=pick([4,6,8]);q=`European options on a non-dividend stock: S₀=$100, K=$100, T=0.5 years, continuously compounded r=4%, put price=$${put}. What must the call cost by parity?`;a=put+S-K*Math.exp(-r*T);work=`C = P + S₀ − Ke^(−rT) = ${money(a)}. Match exercise style, strike and maturity.`;unit='dollars';tol=.1;break;}
 case 'binomial':{const u=pick([120,130,140]),d=pick([70,80,90]),K=100;const cu=u-K;q=`A stock is $100. Next period it is $${u} or $${d}. A call has K=$100. What share quantity Δ replicates the call’s change in payoff?`;a=cu/(u-d);work=`Up payoff = $${cu}; down payoff = $0. Δ = (${cu}−0)/(${u}−${d}) = ${a.toFixed(4)} shares. This hedge ratio does not require actual state probabilities.`;unit='shares';tol=.005;break;}
 case 'carry':{const S=pick([80,100,120]),r=.04,T=.5;q=`A non-income-producing asset costs $${S}. Continuous risk-free rate is 4%, delivery in 0.5 years. Ignore all other carry costs. What is the no-arbitrage forward price?`;a=S*Math.exp(r*T);work=`F₀ = S₀e^(rT) = ${money(a)}. Storage, income and convenience yield would change the carry relation.`;unit='dollars';tol=.1;break;}
 case 'mortgage':{const L=pick([100000,200000,300000]),r=pick([.03,.045,.06]),n=360;q=`A $${L.toLocaleString()} loan amortizes over 30 years with level monthly payments. Nominal annual rate is ${pct(r)}, divided by 12 for monthly interest. What is the monthly payment, excluding taxes, insurance and fees?`;a=mortgage(L,r/12,n);work=`i = ${r}/12; n = 360. Payment = L×i/[1−(1+i)^−n] = ${money(a)}. Each payment includes interest and principal.`;unit='dollars';tol=.1;break;}
 case 'ltv':{const value=pick([200000,400000,600000]),l=pick([.6,.75,.8,.9]);q=`A home is worth $${value.toLocaleString()}; mortgage balance is $${(value*l).toLocaleString()}. What is LTV in percent?`;a=l*100;work=`LTV = mortgage balance / home value = ${a}%. Owner equity before sale costs is the remaining ${100-a}%.`;unit='percent';break;}
 case 'caprate':{const value=pick([500000,800000,1000000]),rate=pick([.04,.05,.06]);q=`Property value is $${value.toLocaleString()}; annual NOI BEFORE debt service is $${(value*rate).toLocaleString()}. What is its cap rate in percent?`;a=rate*100;work=`Cap rate = NOI/property value = ${a.toFixed(2)}%. This excludes debt financing and appreciation.`;unit='percent';break;}
 case 'debt':{const d=pick([.6,.8,1]),r=.05,g=.03,p=pick([.01,.02]);q=`Debt/GDP is ${d*100}%; effective nominal interest r=5%; nominal GDP growth g=3%; primary deficit/GDP=${p*100}%. Using Δd ≈ (r−g)d+p, what is the change in PERCENTAGE POINTS of GDP?`;a=((r-g)*d+p)*100;work=`Δd ≈ (0.05−0.03)×${d}+${p} = ${a.toFixed(2)} percentage points. This approximation excludes valuation and other adjustments.`;unit='percentage points';break;}
 default:throw Error('Unknown calculation '+key);
 }
 return {prompt:q,answer:a,explanation:work,unit,tolerance:tol,answerText:unit==='dollars'?money(a):a.toFixed(unit==='shares'?4:2)+' '+unit};
}
export function parseNumber(text){const s=String(text).trim().replace(/[$,%\s]/g,'');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))return null;const x=Number(s);return Number.isFinite(x)?x:null;}
export function isCorrect(value,result){return value!==null&&Math.abs(value-result.answer)<=result.tolerance+1e-9;}
